// ============================================================
// WhaleTrace Supabase Sync
// 接收爬蟲資料 → 寫入 Supabase (DELETE + INSERT per table)
// ============================================================

const SUPABASE_URL = 'https://vihxecnwonwmqclaxubn.supabase.co';
const SUPABASE_KEY = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InZpaHhlY253b253bXFjbGF4dWJuIiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc3OTU4NTY4OCwiZXhwIjoyMDk1MTYxNjg4fQ.-Tsme1Yakhfrj_nms3fG3TPvoblYS4WBSzO-Ejw5fK0';

const body = $input.first().json;

async function supabaseRequest(method, path, data) {
  const options = {
    method: method,
    url: SUPABASE_URL + path,
    headers: {
      'apikey': SUPABASE_KEY,
      'Authorization': 'Bearer ' + SUPABASE_KEY,
      'Content-Type': 'application/json',
      'Prefer': 'return=minimal'
    },
    json: true
  };
  if (data) options.body = data;
  try {
    await this.helpers.httpRequest(options);
    return 'OK';
  } catch (e) {
    return 'ERR:' + (e.message || e).toString().slice(0, 80);
  }
}

const tickers = body.tickers || [];
const tickerFilter = tickers.length > 0 ? '?ticker=in.(' + tickers.join(',') + ')' : '';
const results = {};

// 1. stock_snapshots
if (body.stock_snapshots && body.stock_snapshots.length > 0) {
  const rows = body.stock_snapshots.map(s => ({
    ticker: s.ticker || '',
    snapshot_date: s.data_date || new Date().toISOString().slice(0,10),
    inst_ownership_pct: s.inst_own_pct,
    insider_ownership_pct: s.insider_own_pct,
    short_float_pct: s.short_float_pct,
    short_ratio: s.short_ratio,
    market_cap: s.market_cap,
    pe_ratio: s.pe_trailing,
    analyst_recommendation: s.recommendation || ''
  }));
  const del = await supabaseRequest('DELETE', '/rest/v1/stock_snapshots' + tickerFilter);
  const ins = await supabaseRequest('POST', '/rest/v1/stock_snapshots', rows);
  results.stock_snapshots = `del=${del} ins=${ins} rows=${rows.length}`;
}

// 2. insider_trades
if (body.insider_trades && body.insider_trades.length > 0) {
  const rows = body.insider_trades.map(t => ({
    ticker: t.ticker || '',
    insider_name: t.insider_name || '',
    role: t.title || '',
    transaction_date: t.trade_date || '',
    filing_date: t.filing_date || '',
    security: 'Common Stock',
    transaction_type: t.transaction_type || '',
    shares: t.shares || 0,
    price: 0,
    value: 0,
    shares_held: 0,
    filing_url: t.filing_url || ''
  }));
  const del = await supabaseRequest('DELETE', '/rest/v1/insider_trades' + tickerFilter);
  const ins = await supabaseRequest('POST', '/rest/v1/insider_trades', rows);
  results.insider_trades = `del=${del} ins=${ins} rows=${rows.length}`;
}

// 3. institutional_holdings
if (body.institutional_holdings && body.institutional_holdings.length > 0) {
  const rows = body.institutional_holdings.map(h => ({
    ticker: h.ticker || '',
    institution_name: h.institution_name || '',
    shares: h.shares || 0,
    market_value: h.market_value || 0,
    change_shares: h.change_shares || 0,
    change_pct: 0,
    portfolio_pct: h.pct_of_portfolio || 0,
    filing_date: h.quarter || '',
    source: 'whaletrace-n8n'
  }));
  const del = await supabaseRequest('DELETE', '/rest/v1/institutional_holdings' + tickerFilter);
  const ins = await supabaseRequest('POST', '/rest/v1/institutional_holdings', rows);
  results.institutional_holdings = `del=${del} ins=${ins} rows=${rows.length}`;
}

results._ts = new Date().toISOString();
return [{ json: results }];
